    //   [R*IR1,G*IR2,B*IR3] SHL 4 = [0x320000, 0xC8000, 0x12C000]
    //   IR1 = ((FC1 SHL 12) - MAC1) SAR 12 = 0xBE0; MAC1 = IR1*IR0 + MAC1 = 0xBE0*0x400 + 0x320000 = 0x618000
    //   IR2 = ((FC2 SHL 12) - MAC2) SAR 12 = -0x48; MAC2 = IR2*IR0 + MAC2 = -0x48*0x400 + 0xC8000 = 0xB6000
    //   IR3 = ((FC3 SHL 12) - MAC3) SAR 12 = -0x12C; MAC3 = IR3*IR0 + MAC3 = -0x12C*0x400 + 0x12C000 = 0xE1000
