    // DPCT sf=1: reads RGB0 three times, CODE from RGBC  (cmd 0x0F8002A)
    //   ctrl in: c8=0xFC000800, c9=0x1000200, c10=0xFD000C00, c11=0x100FE00, c12=0xE00, c13=0x40, c14=0x30, c15=0x20, c16=0x2001000, c17=0x1000100, c18=0x2000E00, c19=0x1000080, c20=0xC00, c21=0xF00, c22=0x80
    //   data in: VXY0=0x4000800, VZ0=0xE00, RGBC=0x34C04080, IR0=0x400, IR1=0x640, IR2=0x320, IR3=0x190
    //   RGB0=0x01020304: [R,G,B] SHL 16 = [0x40000, 0x30000, 0x20000]
    //   IR1 = ((FC1 SHL 12) - MAC1) SAR 12 = 0xEC0; MAC1 = IR1*IR0 + MAC1 = 0xEC0*0x400 + 0x40000 = 0x3F0000
    //   IR2 = ((FC2 SHL 12) - MAC2) SAR 12 = 0x50; MAC2 = IR2*IR0 + MAC2 = 0x50*0x400 + 0x30000 = 0x44000
    //   IR3 = ((FC3 SHL 12) - MAC3) SAR 12 = -0x20; MAC3 = IR3*IR0 + MAC3 = -0x20*0x400 + 0x20000 = 0x18000
    //   MAC1 = 0x3F0000 SAR 12 = 0x3F0; IR1 = 0x3F0
    //   MAC2 = 0x44000 SAR 12 = 0x44; IR2 = 0x44
    //   MAC3 = 0x18000 SAR 12 = 0x18; IR3 = 0x18
    //   R = MAC1/16 = 0x3F
    //   G = MAC2/16 = 0x4
