    //   IR2 = ((FC2 SHL 12) - MAC2) SAR 12 = -0x30; MAC2 = IR2*IR0 + MAC2 = -0x30*0x400 + 0xB0000 = 0xA4000
    //   IR3 = ((FC3 SHL 12) - MAC3) SAR 12 = -0xA0; MAC3 = IR3*IR0 + MAC3 = -0xA0*0x400 + 0xA0000 = 0x78000
    //   MAC1 = 0x450000 SAR 12 = 0x450; IR1 = 0x450
    //   MAC2 = 0xA4000 SAR 12 = 0xA4; IR2 = 0xA4
    //   MAC3 = 0x78000 SAR 12 = 0x78; IR3 = 0x78
    //   R = MAC1/16 = 0x45
    //   G = MAC2/16 = 0xA
    //   B = MAC3/16 = 0x7
