    // INTPL sf=1 lm=1 with a negative IR1  (cmd 0x0980411)
    //   ctrl in: c22=0x10, c23=0xFF0
    //   data in: RGBC=0x3A000000, IR0=0x400, IR1=0xFFFFF800, IR2=0x400, IR3=0x100
